export const localizePrologueWork = (work: PrologueWork, locale: Locale): PrologueWork => {
    if (locale !== 'fr') return work;

    const localized = { ...work, ...FR_PROLOGUE_METADATA[work.slug] };
    const content = FR_PROLOGUE_CONTENT[work.slug];

    return content
        ? {
            ...localized,
            content: localized.content.map((paragraph, index) => content[index] ?? paragraph),
        }
        : localized;
};
